/* Local-only interactive KisanPool Fresh prototype. All market data is simulated. */
(() => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rupee = n => `₹${Math.round(n).toLocaleString('en-IN')}`;
  const places = {
    nashik:{name:'Nashik city',lat:19.9975,lng:73.7898}, lasalgaon:{name:'Lasalgaon',lat:20.1417,lng:74.2389},
    pune:{name:'Pune',lat:18.5204,lng:73.8567}, vashi:{name:'Vashi',lat:19.0662,lng:73.0021},
    sinnar:{name:'Sinnar',lat:19.8453,lng:73.9986}, yeola:{name:'Yeola',lat:20.0424,lng:74.4892}
  };
  const markets = [
    {id:'lasalgaon',name:'Lasalgaon APMC',district:'Nashik',lat:20.1417,lng:74.2389,price:12.5,handling:280,demand:'High',hours:'06:00–18:00',vehicle:'Mini truck',capacity:1200},
    {id:'nashik-yard',name:'Nashik Market Yard',district:'Nashik',lat:19.9975,lng:73.7898,price:12.2,handling:220,demand:'High',hours:'05:00–20:00',vehicle:'Pickup',capacity:650},
    {id:'pune',name:'Pune Market Yard',district:'Pune',lat:18.4805,lng:73.8683,price:13.1,handling:450,demand:'Medium',hours:'05:00–20:00',vehicle:'Truck',capacity:4000},
    {id:'vashi',name:'Vashi APMC',district:'Navi Mumbai',lat:19.0662,lng:73.0021,price:14.8,handling:520,demand:'High',hours:'04:00–19:00',vehicle:'Truck',capacity:4000},
    {id:'ahmednagar',name:'Ahmednagar APMC',district:'Ahmednagar',lat:19.0948,lng:74.7480,price:12.9,handling:300,demand:'Medium',hours:'06:00–17:00',vehicle:'Mini truck',capacity:1200},
    {id:'daund',name:'Daund APMC',district:'Pune',lat:18.4646,lng:74.5815,price:13.3,handling:320,demand:'Medium',hours:'06:30–17:30',vehicle:'Mini truck',capacity:1200}
  ];
  const state = {offers:{}, options:null, category:'balanced', selected:null, pooled:false, request:null,
    quantity:480,sold:180,available:300,inTransit:0,current:'pune',target:'vashi',action:'REROUTE_TO_MARKET',
    approvals:[false,false],version:1,events:[],incident:null,handover:[false,false]};
  const tabButtons = $$('[data-tab]');
  function tabs(id) { tabButtons.forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===id))); $$('[role="tabpanel"]').forEach(p=>{p.hidden=p.id!==id;p.classList.toggle('active',p.id===id);}); }
  tabButtons.forEach(b=>b.addEventListener('click',()=>tabs(b.dataset.tab)));
  document.addEventListener('click',e=>{const c=e.target.closest('[data-choice-group] .choice'); if(c&&!c.disabled){c.parentElement.querySelectorAll('.choice').forEach(x=>x.classList.toggle('selected',x===c));}});

  $('#comparison').innerHTML='<div class="section-head"><div><h2>Market comparison & recommendation</h2><p class="sub">Compare estimated return, timing, and reference market locations.</p></div></div><div class="banner warning"><strong>SIMULATED DATA ONLY</strong><p class="sub">No live market prices, route services, vehicles or buyers.</p></div><div class="choices" id="recommendation-tabs"></div><div id="recommendation-cards"></div><article class="card" id="market-detail" hidden></article><article class="card"><div class="row"><div><strong>Reference market locations</strong><p class="sub">Approximate points in Maharashtra. List and schematic map views.</p></div><div class="choices"><button class="choice selected" data-market-view="list">List</button><button class="choice" data-market-view="map">Map</button></div></div><div id="market-list"></div><div id="market-map" hidden></div></article><article class="card"><strong>Why this recommendation?</strong><p id="why-recommendation" class="sub"></p><div id="recommendation-metrics" class="metrics"></div></article><article class="card"><h3>Record a farmer-reported buyer quote</h3><p class="sub">Unverified prototype input. Re-run comparison to include it.</p><div class="grid"><label class="field"><span>Market</span><select id="offer-market"></select></label><label class="field"><span>Price (₹/kg)</span><input id="offer-price" type="number" min="0" value="14"></label><label class="field"><span>Offer quantity (kg)</span><input id="offer-quantity" type="number" min="1" value="200"></label><label class="field"><span>Valid until</span><input id="offer-expiry" type="datetime-local"></label></div><button class="btn" id="save-offer">Save simulated quote</button><p id="offer-status" class="small muted" role="status"></p></article><article class="card"><div class="row"><strong>Continue to transport</strong><span id="selection-badge" class="badge">No selection</span></div><p id="selection-summary" class="sub">Choose an option above.</p><button class="btn primary" id="select-market" disabled>Select this destination</button> <button class="btn" id="share-summary">Share safe comparison summary</button></article>';
  $('#recovery').innerHTML='<div class="section-head"><div><h2>Vehicle recovery & handover</h2><p class="sub">Simulate a disruption, capacity check and dual custody confirmation.</p></div></div><article class="card"><div class="row"><h3>Report incident</h3><span id="incident-state" class="badge">Trip active</span></div><p id="incident-quantity" class="sub"></p><div class="group"><div class="group-label">Incident type</div><div class="choices" id="incident-types" data-choice-group><button class="choice selected">Vehicle breakdown</button><button class="choice">Road blocked</button><button class="choice">Safety concern</button></div></div><label class="field"><span>What happened?</span><textarea id="incident-description" placeholder="Describe the simulated issue"></textarea></label><button class="btn primary" id="report-incident">Record simulated incident</button><p id="incident-message" class="small muted" role="status"></p></article><article class="card"><div class="row"><h3>Replacement and handover</h3><span id="replacement-state" class="badge warning"></span></div><label class="field"><span>Replacement capacity (kg)</span><input id="replacement-capacity" type="number" min="1" value="800"></label><p id="replacement-quote" class="sub"></p><div class="metrics"><div class="metric"><span>Remaining leg quote</span><strong id="replacement-cost">—</strong></div><div class="metric"><span>Cargo at handover</span><strong id="handover-quantity">—</strong></div></div><label class="approval"><input type="checkbox" data-handover disabled><span>Farmer confirms quantity and condition</span></label><label class="approval"><input type="checkbox" data-handover disabled><span>Replacement driver confirms custody</span></label><div id="handover-state" class="banner warning"></div></article>';
  $('#partial-sale').innerHTML='<div class="section-head"><div><h2>Partial sale · sell here or reroute?</h2><p class="sub">Track remaining cargo and require same-version farmer and transporter consent.</p></div></div><article class="card"><div class="row"><h3>Current market · <span id="current-market-name">Pune Market Yard</span></h3><span class="badge">Simulated cargo ledger</span></div><div class="metrics"><div class="metric"><span>Received</span><strong id="received-amount"></strong></div><div class="metric"><span>Sold</span><strong><span id="sold-amount"></span> kg</strong></div><div class="metric"><span>Available</span><strong><span id="remaining-amount"></span> kg</strong></div><div class="metric"><span>In transit</span><strong><span id="transit-amount">0</span> kg</strong></div></div><label class="field"><span>Total quantity sold here (kg)</span><input id="sale-qty" type="number" min="0" value="180"></label><p id="ledger-state" class="small muted"></p></article><div class="group-label">Action for <span id="remaining-copy"></span> kg</div><button class="action" data-action="SELL_HERE"><span class="radio"></span><span><strong>SELL HERE</strong><br><span class="muted">Use the current market simulated offer</span></span></button><button class="action selected" data-action="REROUTE_TO_MARKET"><span class="radio"></span><span><strong>REROUTE</strong><br><span id="reroute-copy" class="muted"></span></span></button><label class="field"><span>Reroute destination</span><select id="reroute-target"></select></label><button class="action" data-action="HOLD_OR_ESCALATE"><span class="radio"></span><span><strong>HOLD / OPERATIONS</strong><br><span class="muted">Keep custody and ask operations to resolve</span></span></button><article class="card"><div class="row"><h3>Same-option approvals</h3><span id="quote-version" class="badge warning"></span></div><label class="approval"><input type="checkbox" data-approval><span>Farmer confirms choice</span></label><label class="approval"><input type="checkbox" data-approval><span>Transporter confirms route and quote</span></label><div id="approval-state" class="banner warning"></div><button id="execute-cargo-choice" class="btn primary" disabled>Confirm simulated disposition</button><ol id="cargo-events" class="small"></ol></article><p class="meta">SIMULATED ONLY · NO LIVE LEG, PAYMENT OR CUSTODY UPDATE</p>';
  let journey=$('#journey'); if(!journey){journey=document.createElement('section');journey.id='journey';journey.className='panel';journey.setAttribute('role','tabpanel');journey.hidden=true;$('.shell').insertBefore(journey,$('.footer'));}
  journey.innerHTML='<div class="section-head"><div><h2>Transport handoff & delivery outcome</h2><p class="sub">Continue a recommendation into a simulated request and record farmer-reported results.</p></div></div><article class="card"><div class="row"><h3>Selected destination</h3><span id="journey-state" class="badge"></span></div><p id="journey-summary" class="sub"></p><p class="meta">NO CAPACITY RESERVATION · NO PAYMENT CREATED</p></article><article class="card"><h3>Delivery outcome</h3><div class="grid"><label class="field"><span>Actual price (₹/kg)</span><input id="actual-price" type="number" min="0" value="12"></label><label class="field"><span>Accepted kg</span><input id="actual-accepted" type="number" min="0" value="400"></label><label class="field"><span>Rejected kg</span><input id="actual-rejected" type="number" min="0" value="0"></label><label class="field"><span>Extra costs (₹)</span><input id="actual-costs" type="number" min="0" value="0"></label></div><button id="record-outcome" class="btn primary">Save farmer-reported outcome</button><p id="outcome-status" class="small muted" role="status"></p><div id="outcome-variance" class="metrics"></div></article>';

  const pickup=$('#pickup-place'), qty=$('#quantity'), harvested=$('#harvested');
  const localTime=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
  harvested.value=localTime(new Date(Date.now()-5*3600000));
  const pooling=document.createElement('label'); pooling.className='approval'; pooling.innerHTML='<input id="pooling-toggle" type="checkbox"><span>Include compatible simulated second batch (220 kg) and split shared transport cost</span>';
  $('#produce .card').append(pooling);
  pickup.addEventListener('change',()=>{const p=places[pickup.value];$('#pickup-description').textContent=`${p.name} reference point · ${p.lat.toFixed(4)}, ${p.lng.toFixed(4)}. Approximate road distance; use route link for map directions.`;validate();});
  $('#pooling-toggle').addEventListener('change',e=>{state.pooled=e.target.checked;validate();});
  [qty,harvested].forEach(i=>i.addEventListener('input',validate));
  function validate(){const n=Number(qty.value),t=new Date(harvested.value).getTime(),ok=Number.isFinite(n)&&n>0&&n<=100000&&Number.isFinite(t)&&t<=Date.now();$('#compare-markets').disabled=!ok;$('#form-message').textContent=ok?`Ready to compare ${n.toLocaleString('en-IN')} kg tomatoes from ${places[pickup.value].name}. Simulated results only.`:'Enter a positive quantity (up to 100,000 kg) and a valid harvest time in the past.';return ok;}
  const rad=x=>x*Math.PI/180;
  function km(a,b){let d1=rad(b.lat-a.lat),d2=rad(b.lng-a.lng),h=Math.sin(d1/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(d2/2)**2;return 6371*2*Math.asin(Math.sqrt(h));}
  const duration=m=>{let h=Math.floor(m/60),r=Math.round(m%60);return h?`${h}h ${r}m`:`${r}m`;};
  const choice=(group)=>$(`${group} .selected`)?.textContent.trim()||'';
  const labeledChoice=(label)=>{const group=$$('#produce .group').find(g=>$('.group-label',g)?.textContent.includes(label));return group?$('.choice.selected',group)?.textContent.trim()||'':'';};
  function calculate(){const origin=places[pickup.value],n=Number(qty.value),total=n+(state.pooled?220:0),age=Math.max(0,(Date.now()-new Date(harvested.value))/3600000);const ripeness=labeledChoice('Ripeness').toLowerCase(),storage=labeledChoice('Storage').toLowerCase(),deadline=labeledChoice('When would');
    const all=markets.map(m=>{const direct=km(origin,m),road=direct*1.28,minutes=Math.max(8,road/38*60)+35,capacity=total<=m.capacity,trip=Math.round(road*(12+total/250)),farmerTrip=state.pooled?Math.round(trip*n/total):trip,risk=Math.min(95,Math.round(age*2.1+(ripeness==='ripe'?20:ripeness==='turning'?10:4)+(storage==='ambient'?16:storage==='cool'?0:storage==='unknown'?12:4))),saleable=n*(1-risk/600),reported=state.offers[m.id],offer=reported&&reported.expiry>Date.now()&&reported.amount>=n?reported:null,price=offer?.price??m.price,net=Math.round(saleable*price-farmerTrip-m.handling),limit=deadline==='Today'?8:deadline==='12 hours'?12:deadline==='24 hours'?24:deadline==='48 hours'?48:48,fit=Math.max(0,100-minutes/limit*100);return {...m,origin,direct,road,minutes,capacity,trip,farmerTrip,risk,saleable,price,offer,net,fit,score:Math.round((Math.min(100,Math.max(0,net/Math.max(1,n*15)*100))+fit)/2)};});
    const eligible=all.filter(x=>x.capacity);if(!eligible.length)return {all,eligible,cats:null};const byNet=(a,b)=>b.net-a.net;return {all,eligible,cats:{balanced:[...eligible].sort((a,b)=>b.score-a.score||byNet(a,b))[0],net:[...eligible].sort(byNet)[0],fast:[...eligible].sort((a,b)=>a.minutes-b.minutes)[0],near:[...eligible].sort((a,b)=>a.road-b.road)[0]}};
  }
  function selectedOption(){return state.options?.all.find(m=>m.id===state.selected);}
  function drawMap(){const all=state.options.all,origin=places[pickup.value],lats=[origin.lat,...all.map(x=>x.lat)],lngs=[origin.lng,...all.map(x=>x.lng)],minY=Math.min(...lats)-.1,maxY=Math.max(...lats)+.1,minX=Math.min(...lngs)-.1,maxX=Math.max(...lngs)+.1;const xy=p=>({x:35+(p.lng-minX)/(maxX-minX)*620,y:25+(maxY-p.lat)/(maxY-minY)*310}),o=xy(origin);$('#market-map').innerHTML=`<svg viewBox="0 0 700 370" style="width:100%;height:auto;background:var(--card);border-radius:12px" aria-label="Schematic coordinate map"><path d="M40 80 C180 120 250 220 380 150 S550 250 660 300" fill="none" stroke="var(--line)" stroke-width="18"/>${all.map(m=>{const p=xy(m);return `<g class="map-pin" data-detail="${m.id}" tabindex="0" role="button"><line x1="${o.x}" y1="${o.y}" x2="${p.x}" y2="${p.y}" stroke="#aaa" stroke-dasharray="5 5"/><circle cx="${p.x}" cy="${p.y}" r="8" fill="${m.id===state.selected?'#166534':'#b45309'}"/><text x="${p.x+10}" y="${p.y+4}" fill="currentColor" font-size="12">${esc(m.name)}</text></g>`;}).join('')}<circle cx="${o.x}" cy="${o.y}" r="10" fill="#1d4ed8"/><text x="${o.x+12}" y="${o.y-10}" fill="currentColor" font-size="12">Pickup</text></svg><p class="small muted">Schematic reference points, not a live road map. Distances and ETAs are approximate.</p>`;}
  function renderComparison(){const {all,eligible,cats}=state.options;const names={balanced:'Best balanced',net:'Highest net proceeds',fast:'Fastest feasible',near:'Closest suitable'};if(!cats){state.selected=null;$('#recommendation-tabs').innerHTML='';$('#recommendation-cards').innerHTML='<div class="banner warning">No listed simulated vehicle can carry this quantity. Reduce quantity or include compatible pooling.</div>';$('#market-list').innerHTML='';$('#market-detail').hidden=true;renderSelection();return;}
    state.selected=cats[state.category]?.id||cats.balanced.id;$('#recommendation-tabs').innerHTML=Object.entries(names).map(([k,v])=>`<button class="choice ${state.category===k?'selected':''}" data-category="${k}">${v}</button>`).join('');const main=cats[state.category];$('#recommendation-cards').innerHTML=`<article class="card featured"><div class="row"><strong>${names[state.category]}</strong><span class="badge success">${main.score}/100 balance score</span></div><h3>${esc(main.name)}</h3><p class="sub">${rupee(main.net)} estimated net · ${duration(main.minutes)} · ${rupee(main.farmerTrip)} transport · ₹${main.price.toFixed(2)}/kg</p><p class="small muted">${main.district} · receives ${main.hours} · freshness risk indicator ${main.risk}/100 · ${main.capacity?'capacity fit':'capacity not fit'}</p><button class="btn" data-detail="${main.id}">View location & details</button> <button class="btn primary" data-pick="${main.id}">Select this option</button><p class="meta">SIMULATED, NOT A LIVE PRICE OR VEHICLE</p></article><div class="grid">${eligible.map(m=>`<article class="card"><div class="row"><strong>${esc(m.name)}</strong><span class="badge">${m.road.toFixed(0)} km</span></div><p class="sub">${rupee(m.net)} net · ${duration(m.minutes)} · ₹${m.price.toFixed(2)}/kg</p><button class="btn" data-detail="${m.id}">Details</button> <button class="btn" data-pick="${m.id}">Select</button></article>`).join('')}</div>`;
    $('#market-list').innerHTML=all.map(m=>`<article class="card"><div class="row"><div><strong>${esc(m.name)}</strong><p class="sub">${esc(m.district)}, Maharashtra · ${m.road.toFixed(1)} km approximate road · ${duration(m.minutes)}</p></div><span class="badge ${m.capacity?'success':'warning'}">${m.capacity?'Capacity fit':'Reference only'}</span></div><p class="small muted">${m.lat.toFixed(5)}, ${m.lng.toFixed(5)} · receives ${m.hours} · ${m.vehicle}, ${m.capacity.toLocaleString('en-IN')} kg · ${m.demand} simulated demand</p><div class="row"><span class="small muted">₹${m.price.toFixed(2)}/kg simulated benchmark</span><a class="btn" target="_blank" rel="noreferrer" href="https://www.google.com/maps/dir/?api=1&origin=${m.origin.lat},${m.origin.lng}&destination=${m.lat},${m.lng}">Directions ↗</a></div></article>`).join('');drawMap();renderDetail(state.selected);renderSelection();}
  function renderDetail(id){const m=state.options?.all.find(x=>x.id===id);const box=$('#market-detail');if(!m){box.hidden=true;return;}box.hidden=false;box.innerHTML=`<div class="row"><h3>${esc(m.name)} · ${esc(m.district)}</h3><span class="badge warning">Reference location</span></div><p class="sub">Maharashtra · ${m.lat.toFixed(5)}, ${m.lng.toFixed(5)} · receiving hours ${m.hours}</p><div class="metrics"><div class="metric"><span>Approx road distance</span><strong>${m.road.toFixed(1)} km</strong></div><div class="metric"><span>ETA estimate</span><strong>${duration(m.minutes)}</strong></div><div class="metric"><span>Transport quote</span><strong>${rupee(m.trip)}</strong></div><div class="metric"><span>Reference price</span><strong>₹${m.price.toFixed(2)}/kg</strong></div><div class="metric"><span>Estimated net</span><strong>${rupee(m.net)}</strong></div><div class="metric"><span>Listed capacity</span><strong>${m.capacity.toLocaleString('en-IN')} kg</strong></div></div><p class="small muted">Prototype fixture; market hours, crop acceptance, buyer price and vehicle availability are not verified.</p><a class="btn" target="_blank" rel="noreferrer" href="https://www.google.com/maps/dir/?api=1&origin=${m.origin.lat},${m.origin.lng}&destination=${m.lat},${m.lng}">Open directions in Google Maps ↗</a>`;}
  function renderSelection(){const m=selectedOption();$('#select-market').disabled=!m||!m.capacity;$('#selection-badge').textContent=m?'Destination selected':'No selection';$('#selection-summary').textContent=m?`${m.name} · ${m.road.toFixed(1)} km · ${duration(m.minutes)} · transport ${rupee(m.farmerTrip)}. Prototype only; no capacity reserved.`:'Select a market option above.';$('#why-recommendation').textContent=m?`${m.name}: score combines estimated net proceeds (${rupee(m.net)}) with requested delivery fit (${Math.round(m.fit)}/100). Freshness risk ${m.risk}/100 affects saleable quantity estimate.`:'Choose a recommendation to inspect its score inputs.';$('#recommendation-metrics').innerHTML=m?[['Net estimate',rupee(m.net)],['Delivery fit',`${Math.round(m.fit)}/100`],['Freshness risk',`${m.risk}/100`],['Balanced score',`${m.score}/100`]].map(x=>`<div class="metric"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join(''):'';}
  function compare(){if(!validate())return;state.quantity=Number(qty.value);state.options=calculate();state.category='balanced';state.request=null;if(state.options.cats)state.selected=state.options.cats.balanced.id;state.sold=Math.min(180,Math.floor(state.quantity*.375));state.available=state.quantity-state.sold;state.inTransit=0;state.events=[];renderComparison();renderCargo();tabs('comparison');}
  $('#compare-markets').addEventListener('click',compare);
  $('#recommendation-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b||!state.options?.cats)return;state.category=b.dataset.category;renderComparison();});
  $('#recommendation-cards').addEventListener('click',e=>{const d=e.target.closest('[data-detail]'),p=e.target.closest('[data-pick]');if(d){renderDetail(d.dataset.detail);state.selected=d.dataset.detail;renderSelection();drawMap();}if(p){state.selected=p.dataset.pick;renderDetail(state.selected);renderSelection();drawMap();}});
  $$('[data-market-view]').forEach(b=>b.addEventListener('click',()=>{$$('[data-market-view]').forEach(x=>x.classList.toggle('selected',x===b));const map=b.dataset.marketView==='map';$('#market-map').hidden=!map;$('#market-list').hidden=map;}));
  $('#market-map').addEventListener('click',e=>{const pin=e.target.closest('[data-detail]');if(pin){state.selected=pin.dataset.detail;renderDetail(state.selected);renderSelection();drawMap();}});
  $('#select-market').addEventListener('click',()=>{renderJourney();tabs('journey');});
  $('#share-summary').addEventListener('click',async()=>{const m=selectedOption();if(!m)return;const summary=`KisanPool Fresh prototype · ${state.quantity} kg tomatoes · ${m.name} · ${m.road.toFixed(1)} km approx · ${rupee(m.net)} estimated net. SIMULATED.`;try{if(navigator.share)await navigator.share({title:'KisanPool Fresh comparison',text:summary});else{await navigator.clipboard.writeText(summary);$('#selection-summary').textContent=`${summary} Copied to clipboard.`;}}catch(e){$('#selection-summary').textContent=summary;}});
  $('#save-offer').addEventListener('click',()=>{const id=$('#offer-market').value,price=Number($('#offer-price').value),amount=Number($('#offer-quantity').value),expiry=new Date($('#offer-expiry').value);if(!(price>=0&&amount>0&&expiry>new Date())){$('#offer-status').textContent='Enter a valid price, positive quantity and future expiry.';return;}state.offers[id]={price,amount,expiry};$('#offer-status').textContent=`Saved as unverified farmer-reported quote: ₹${price.toFixed(2)}/kg for ${amount} kg. Re-run comparison to apply.`;});
  $('#offer-market').innerHTML=markets.map(m=>`<option value="${m.id}">${m.name}</option>`).join('');$('#offer-expiry').value=localTime(new Date(Date.now()+4*3600000));

  function renderJourney(){const m=selectedOption();if(!m){$('#journey-summary').textContent='Choose a destination in market comparison first.';return;}$('#journey-state').textContent=state.request?'Prototype request created':'Ready for simulated request';$('#journey-summary').innerHTML=state.request?`Request ${esc(state.request)} · ${state.quantity} kg · ${esc(places[pickup.value].name)} → ${esc(m.name)} · estimate ${rupee(m.farmerTrip)}. No booking/payment created.`:`${esc(m.name)} · estimated net ${rupee(m.net)} · arrival ${m.arrival||new Date(Date.now()+m.minutes*60000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} · ${esc(m.vehicle)} capacity ${m.capacity} kg. <button class="btn primary" id="create-request">Create prototype request</button>`;$('#create-request')?.addEventListener('click',()=>{state.request=`DEMO-${Math.random().toString(36).slice(2,8).toUpperCase()}`;renderJourney();});}
  $('#record-outcome').addEventListener('click',()=>{const m=selectedOption(),p=Number($('#actual-price').value),a=Number($('#actual-accepted').value),r=Number($('#actual-rejected').value),c=Number($('#actual-costs').value);if(!m){$('#outcome-status').textContent='Select a recommendation first.';return;}if([p,a,r,c].some(x=>!Number.isFinite(x)||x<0)||a+r>state.quantity){$('#outcome-status').textContent='Use non-negative values; accepted plus rejected quantity cannot exceed batch size.';return;}const actual=a*p-m.farmerTrip-c;$('#outcome-status').textContent='Saved locally as a farmer-reported prototype outcome.';$('#outcome-variance').innerHTML=[['Estimated net',rupee(m.net)],['Reported net',rupee(actual)],['Difference',rupee(actual-m.net)]].map(x=>`<div class="metric"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');});

  function resetConsents(){state.approvals=[false,false];state.version++;$$('[data-approval]').forEach(x=>x.checked=false);renderCargo();}
  function renderCargo(){if(!$('#received-amount'))return;const current=markets.find(m=>m.id===state.current)||markets[0],target=markets.find(m=>m.id===state.target)||markets[3];$('#current-market-name').textContent=current.name;$('#received-amount').textContent=`${state.quantity} kg`;$('#sold-amount').textContent=state.sold;$('#remaining-amount').textContent=state.available;$('#transit-amount').textContent=state.inTransit;$('#remaining-copy').textContent=state.available;$('#sale-qty').value=state.sold;$('#sale-qty').max=state.quantity;const d=km(current,target)*1.28,cost=Math.round(d*(12+state.available/250)),rev=Math.round(state.available*target.price-cost-target.handling),sell=state.available*(state.offers[current.id]?.price??current.price);$('#reroute-copy').textContent=`${state.available} kg → ${target.name} · ${d.toFixed(0)} km · added cost ${rupee(cost)} · estimated net ${rupee(rev)}. Sell here estimate ${rupee(sell)}.`;const valid=Number($('#sale-qty').value)>=state.sold&&Number($('#sale-qty').value)<=state.quantity;$('#ledger-state').textContent=valid?`${state.quantity} kg received = ${state.sold} sold + ${state.available} available + ${state.inTransit} in transit. ${state.events.length} events.`:'Sale quantity must be within received quantity.';$('#quote-version').textContent=`Quote v${state.version} · simulated`;$('#cargo-events').innerHTML=state.events.map(x=>`<li>${esc(x)}</li>`).join('');updateConsents();}
  function updateConsents(){const all=state.approvals.every(Boolean);$('#approval-state').className=`banner ${all?'success':'warning'}`;$('#approval-state').textContent=all?`${state.action}: both parties approved quote v${state.version}.`:'Waiting for farmer and transporter approval of the same choice and quote version.';$('#execute-cargo-choice').disabled=!all||state.available<=0;}
  $('#reroute-target').innerHTML=markets.map(m=>`<option value="${m.id}" ${m.id===state.target?'selected':''}>${m.name}</option>`).join('');$('#reroute-target').addEventListener('change',e=>{state.target=e.target.value;resetConsents();});
  $('#sale-qty').addEventListener('input',()=>{const value=Number($('#sale-qty').value);if(!Number.isFinite(value)||value<0||value>state.quantity){$('#ledger-state').textContent=`Enter total sold between 0 and ${state.quantity} kg.`;return;}state.sold=value;state.available=state.quantity-state.sold;resetConsents();});
  $$('[data-action]').forEach(b=>b.addEventListener('click',()=>{state.action=b.dataset.action;$$('[data-action]').forEach(x=>x.classList.toggle('selected',x===b));resetConsents();}));
  $$('[data-approval]').forEach((x,i)=>x.addEventListener('change',()=>{state.approvals[i]=x.checked;updateConsents();}));
  $('#execute-cargo-choice').addEventListener('click',()=>{if(!state.approvals.every(Boolean)||state.available<=0)return;if(state.action==='SELL_HERE'){state.events.push(`${state.available} kg sold at ${markets.find(m=>m.id===state.current).name}, farmer-reported simulated offer.`);state.sold+=state.available;state.available=0;}else if(state.action==='REROUTE_TO_MARKET'){const n=state.available;state.available=0;state.inTransit+=n;state.events.push(`${n} kg dispatched on simulated child leg to ${markets.find(m=>m.id===state.target).name}.`);if(!$('#receive-reroute'))$('#cargo-events').insertAdjacentHTML('afterend','<button class="btn" id="receive-reroute">Simulate arrival at next market</button>');}else state.events.push(`Operations escalation for ${state.available} kg; cargo remains in custody.`);state.approvals=[false,false];state.version++;renderCargo();});
  $('#partial-sale').addEventListener('click',e=>{if(e.target.id==='receive-reroute'){state.inTransit=0;state.available=state.quantity-state.sold;state.current=state.target;state.events.push(`${state.available} kg received at ${markets.find(m=>m.id===state.current).name}; ready for next decision.`);e.target.remove();resetConsents();}});

  function renderRecovery(){const cargo=state.available||state.quantity,cap=Number($('#replacement-capacity').value),fit=cap>=cargo;$('#incident-quantity').textContent=`${cargo} kg · reported condition`;$('#replacement-state').textContent=fit?'Simulated capacity fit':'No replacement fits';$('#replacement-state').className=`badge ${fit?'warning':'danger'}`;$('#replacement-quote').textContent=fit?`Capacity ${cap} kg covers ${cargo} kg. Revised leg quote ${rupee(Math.max(300,cargo*2.45))}.`:`No listed replacement fits ${cargo} kg. Escalate; cargo stays with current custodian.`;$('#replacement-cost').textContent=fit?rupee(Math.max(300,cargo*2.45)):'Not available';$$('[data-handover]').forEach((x,i)=>{x.disabled=!fit||!state.incident;x.checked=state.handover[i];});const all=fit&&state.incident&&state.handover.every(Boolean);$('#handover-state').className=`banner ${all?'success':'warning'}`;$('#handover-state').textContent=all?'Both custody parties acknowledged the simulated handover.':!state.incident?'Record a simulated incident before handover.':fit?'Waiting for both farmer and replacement driver acknowledgement.':'No capacity match; cargo stays with current custodian.';if(all)$('#incident-state').textContent='Replacement handover recorded';}
  $('#replacement-capacity').addEventListener('input',renderRecovery);$('#report-incident').addEventListener('click',()=>{const desc=$('#incident-description').value.trim();if(!desc){$('#incident-message').textContent='Describe the simulated issue first.';return;}state.incident={id:`INC-DEMO-${Date.now().toString().slice(-5)}`,type:choice('#incident-types'),desc};$('#incident-state').textContent='Simulated incident recorded';$('#incident-message').textContent=`${state.incident.id} · ${state.incident.type}. No alert sent.`;renderRecovery();});$$('[data-handover]').forEach((x,i)=>x.addEventListener('change',()=>{state.handover[i]=x.checked;renderRecovery();}));
  renderCargo();renderRecovery();validate();
})();
